"""Lazy registration for web analysis tools."""

from ctfforge.core.registry import ToolRegistry
from ctfforge.core.tool import InteractiveInput as I, ToolSpec


def register_web_tools(registry: ToolRegistry) -> None:
    registry.register_category("web", (
        ToolSpec("jwt", "web", "Decode and statically inspect JWT structure and claims.", "ctfforge.web.jwt_analyzer:analyze", usage="ctfforge web jwt --token TOKEN", help="Decoding does not authenticate a JWT; signatures are never verified.", interactive_inputs=(I("token", "JWT token"),)),
        ToolSpec("headers", "web", "Review HTTP security response headers.", "ctfforge.web.headers:analyze", usage="ctfforge web headers (--url URL | --header HEADER)", help="Fetches headers only when --url is supplied; absence alone does not prove vulnerability.", interactive_inputs=(I("url", "URL to fetch (blank to supply headers)", required=False, group="source", group_rule="exactly_one"), I("header", "Response header in Name: value form (blank to finish)", required=False, multiple=True, group="source", group_rule="exactly_one"))),
        ToolSpec("cookies", "web", "Review cookie flags, scope, and lifetime.", "ctfforge.web.cookies:analyze", usage="ctfforge web cookies (--url URL | --header 'Set-Cookie: ...')", help="Cookie values are redacted by default.", interactive_inputs=(I("url", "URL to fetch (blank to supply Set-Cookie headers)", required=False, group="source", group_rule="exactly_one"), I("header", "Set-Cookie header in Name: value form (blank to finish)", required=False, multiple=True, group="source", group_rule="exactly_one"))),
        ToolSpec("cors", "web", "Review CORS response policy headers.", "ctfforge.web.cors:analyze", usage="ctfforge web cors (--url URL | --header HEADER)", help="Uses a controlled OPTIONS request when fetching; findings indicate risk, not exploitability.", interactive_inputs=(I("url", "URL to send a controlled OPTIONS request to (blank to supply headers)", required=False, group="source", group_rule="exactly_one"), I("header", "Response header in Name: value form (blank to finish)", required=False, multiple=True, group="source", group_rule="exactly_one"))),
        ToolSpec("url", "web", "Parse and inspect a URL without visiting it.", "ctfforge.web.url_analyzer:analyze", usage="ctfforge web url --input URL", interactive_inputs=(I("input", "URL to inspect (this tool will not visit it)"),)),
        ToolSpec("discover", "web", "Perform bounded HTTP path discovery against an authorized target.", "ctfforge.web.directory_discovery:analyze", usage="ctfforge web discover --url URL --wordlist FILE", help="Only run against explicitly authorized targets. No recursion, exploitation, or cross-host redirect following.", interactive_inputs=(I("url", "Explicitly authorized HTTP(S) target URL"), I("wordlist", "Local wordlist path", "path", must_exist=True), I("timeout", "Request timeout in seconds", "float", default=5.0, minimum=0.2, maximum=30), I("rate", "Maximum requests per second", "float", default=2.0, minimum=0.1, maximum=10), I("concurrency", "Maximum worker count (1-5)", "int", default=2, minimum=1, maximum=5), I("status", "Optional allowed status code (blank to finish)", "int", required=False, multiple=True, minimum=100, maximum=599))),
    ))
